        assertTrue("1->0 unreachable", !r.isReachable(1, 0));
        assertTrue("1->0 empty path", r.getPath(1, 0).isEmpty());
    }

    private static void testSingleVertex() {
        FloydWarshall.Result r = FloydWarshall.compute(new int[][]{{0}});
